KEY=`college-connect-${authSession.id}`;data=load();try{const response=await fetch('/api/community',{credentials:'same-origin',cache:'no-store'});if(response.ok){const result=await response.json();if(result.community)data={...data,...result.community,user:data.user,saved:result.community.saved||[]}}}catch{}
