function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2500)}
function roleLabel(role){return ({junior:'Junior',senior:'Senior',alumni:'Alumni',admin:'Administrator'})[role]||'Student'}
function isMentor(p){return p.role==='senior'||p.role==='alumni'}
function roleYear(p){return p.role==='alumni'?'Alumni · '+(p.year||'Graduate'):(roleLabel(p.role)+' · '+(p.year||''))}
function mentorMatch(m){const interests=((data.user.skills||[]).join(' ')+' '+(data.user.goals||'')+' '+(data.user.headline||'')).toLowerCase();const terms=[...(m.skills||[]),...(m.topics||[])];const hits=terms.filter(term=>term.length>2&&interests.includes(term.toLowerCase())).length;return Math.min(99,Math.max(72,Math.round(76+hits*7+(m.department===data.user.department?5:0))))}
