function activeMentors(){return data.mentors.filter(m=>m.id!==data.user.id&&m.available&&data.verifiedIds.includes(m.id))}
function renderMentorCard(m){const verified=data.verifiedIds.includes(m.id),tags=(m.skills||[]).slice(0,3).map(s=>`<span class="tag">${esc(s)}</span>`).join('');return `<article class="mentor-card"><div class="mentor-top"><span class="mentor-avatar ${esc(m.tone||'')} ${m.photo?'has-photo':''}">${avatarContents(m)}</span>${verified?'<span class="verify-mark">✓ Verified</span>':'<span class="verify-mark" style="background:#f5f2e9;color:#9a855b">Community</span>'}</div><h3>${esc(m.name)}</h3><div class="mentor-title">${esc(m.headline||m.department+' · Mentor')}</div><div class="mentor-dept">${esc(m.department)} · ${esc(m.place||'College Connect community')}</div><div class="tag-list">${tags}</div><div class="mentor-foot"><small>${mentorMatch(m)}% match · ${esc(roleYear(m))}</small><button data-mentor-action="${esc(m.id)}">View profile ↗</button></div></article>`}
function renderHome(){const role=data.user.role,first=(data.user.name||'friend').trim().split(' ')[0],hero=$('#home-hero-title'),heroText=$('#home-hero-description'),heroAction=$('#home-hero-action');hero.textContent='Welcome back, '+first+'! 👋';if(role==='admin'){heroText.textContent='Your care helps keep this college community useful, welcoming, and safe.';heroAction.dataset.goto='admin';heroAction.innerHTML='Care for your community <span>↗</span>'}else if(role==='senior'){heroText.textContent='Share what you know, meet alumni, and help another student move forward.';heroAction.dataset.goto='community';heroAction.innerHTML='Share guidance <span>↗</span>'}else if(role==='alumni'){heroText.textContent='Your experience can open a door for someone finding their way.';heroAction.dataset.goto='opportunities';heroAction.innerHTML='Explore the community <span>↗</span>'}else{heroText.textContent='Ready to connect, learn, and grow with your college community?';heroAction.dataset.goto='mentors';heroAction.innerHTML='Find a mentor <span>↗</span>'}const ms=activeMentors().sort((a,b)=>mentorMatch(b)-mentorMatch(a)).slice(0,3);$('#featured-mentors').innerHTML=ms.map(renderMentorCard).join('')||'<div class="empty-state">Mentor suggestions will appear as verified mentors become available.</div>';const ownRequests=data.requests.filter(r=>r.from===data.user.id||r.to===data.user.id),connections=ownRequests.filter(r=>r.status==='accepted').length,pending=ownRequests.filter(r=>r.status==='pending').length;$('#stat-connections').textContent=connections;$('#stat-requests').textContent=pending;$('#stat-questions').textContent=data.posts.filter(p=>p.kind!=='guidance').length;$('#stat-opportunities').textContent=data.opportunities.length;$('#home-opportunities').innerHTML=data.opportunities.slice(0,3).map(renderOpportunity).join('')||'<div class="empty-state">New opportunities shared by alumni will appear here.</div>';const recentRequests=ownRequests.slice(0,2).map(r=>{const other=data.mentors.find(m=>m.id===(r.from===data.user.id?r.to:r.from));return{icon:'♧',tone:'activity-purple',title:r.status==='accepted'?'Connection request accepted':r.status==='rejected'?'Request declined':r.from===data.user.id?'Mentorship request sent':'New mentorship request',detail:other?(r.from===data.user.id?'With ':'From ')+other.name:r.message,time:r.created||'Recently'}}),recentPosts=data.posts.slice(0,2).map(p=>({icon:p.kind==='guidance'?'✦':'▤',tone:p.kind==='guidance'?'activity-green':'activity-blue',title:p.kind==='guidance'?'New guidance shared':'New community question',detail:p.title,time:p.time||'Recently'})),recentOpps=data.opportunities.slice(0,2).map(o=>({icon:'↗',tone:'activity-orange',title:'Opportunity shared',detail:o.title,time:o.date||'Recently'})),activity=[...recentRequests,...recentPosts,...recentOpps].slice(0,5);$('#home-activity').innerHTML=activity.length?activity.map(a=>'<article class="activity-item"><span class="activity-icon '+a.tone+'">'+a.icon+'</span><span class="activity-copy"><b>'+esc(a.title)+'</b><small>'+esc(a.detail)+'</small></span><time>'+esc(a.time)+'</time></article>').join(''):'<div class="empty-state">Your community activity will show here.</div>';const actions=role==='admin'?[['admin','⚑','Review community','Verify profiles and handle reports'],['community','▤','Check discussions','Keep conversations helpful'],['opportunities','↗','Explore opportunities','See what members are sharing']]:role==='alumni'?[['requests','✉','Review requests','Respond to mentorship and connection requests'],['community','▤','Share your guidance','Answer a student’s question'],['opportunities','↗','Share an opportunity','Pass along a useful lead']]:role==='senior'?[['requests','✉','Review requests','Respond to junior mentorship requests'],['mentors','♧','Connect with alumni','Ask for a connection or referral'],['community','▤','Share your guidance','Post a tip or answer a junior’s question']]:[['mentors','♧','Find a mentor','Send a request to a verified senior or alumnus'],['requests','✉','Track sent requests','Follow responses from mentors you contacted'],['community','▤','Ask the community','Get help with your next step']];$('#home-shortcuts').innerHTML=actions.map(([page,icon,title,description])=>'<button class="home-shortcut" data-goto="'+page+'"><span class="shortcut-icon">'+icon+'</span><span class="shortcut-copy"><b>'+title+'</b><small>'+description+'</small></span><span class="shortcut-arrow">→</span></button>').join('')}
function renderGlobalSearch(){const input=$('#global-search'),box=$('#global-search-results'),q=input.value.trim().toLowerCase();if(!q){box.hidden=true;box.innerHTML='';return}const mentors=data.mentors.filter(m=>`${m.name} ${m.headline||''} ${m.department||''} ${(m.skills||[]).join(' ')} ${(m.topics||[]).join(' ')}`.toLowerCase().includes(q)).slice(0,3).map(m=>({kind:'mentor',query:m.name,title:m.name,detail:(m.role==='alumni'?'Alumni':'Senior')+' · '+(m.headline||m.department||'Mentor'),icon:'♧'})),posts=data.posts.filter(p=>`${p.title} ${p.body} ${p.category}`.toLowerCase().includes(q)).slice(0,2).map(p=>({kind:'question',query:p.title,title:p.title,detail:(p.kind==='guidance'?'Guidance':'Community question')+' · '+p.category,icon:p.kind==='guidance'?'✦':'▤'})),opportunities=data.opportunities.filter(o=>`${o.title} ${o.company} ${o.description} ${(o.tags||[]).join(' ')}`.toLowerCase().includes(q)).slice(0,3).map(o=>({kind:'opportunity',query:o.title,title:o.title,detail:o.type+' · '+o.company,icon:'↗'})),items=[...mentors,...posts,...opportunities].slice(0,7);box.innerHTML=items.length?items.map(item=>`<button type="button" class="global-result" data-global-result="${item.kind}" data-global-query="${esc(item.query)}"><span class="global-result-icon">${item.icon}</span><span><b>${esc(item.title)}</b><small>${esc(item.detail)}</small></span><i>↗</i></button>`).join(''):'<div class="global-result-empty">No matching mentors, questions, or opportunities.</div>';box.hidden=false}
function renderMentors(){const q=$('#mentor-search').value.trim().toLowerCase(),role=$('#mentor-role').value,dept=$('#mentor-department').value,sort=$('#mentor-sort').value;let people=activeMentors().filter(m=>(role==='all'||m.role===role)&&`${m.name} ${m.headline} ${m.department} ${(m.skills||[]).join(' ')} ${(m.topics||[]).join(' ')}`.toLowerCase().includes(q)&&(dept==='all'||m.department===dept));if(sort==='name')people.sort((a,b)=>a.name.localeCompare(b.name));else people.sort((a,b)=>mentorMatch(b)-mentorMatch(a));$('#mentor-result-count').textContent=`${people.length} ${people.length===1?'person':'people'} ${q||dept!=='all'?'found':'to learn from'}`;$('#mentor-directory').innerHTML=people.length?people.map(renderMentorCard).join(''):'<div class="empty-state" style="grid-column:1/-1">No mentors match those filters yet. Try another search.</div>'}
function renderPost(p){const liked=(p.likedBy||[]).includes(data.user.id),guidance=p.kind==='guidance',author=p.authorId===data.user.id?data.user:data.mentors.find(m=>m.id===p.authorId),photo=p.authorPhoto||author?.photo;return `<article class="post-card ${guidance?'guidance-post':''}"><div class="post-head"><span class="avatar ${p.authorTone||''} ${photo?'has-photo':''}">${photo?'<img src="'+esc(photo)+'" alt="">':esc(p.initials||initials(p.author))}</span><span class="post-author"><b>${esc(p.author)}</b><small>${esc(roleLabel(p.role))} · ${esc(p.time)}</small></span><span class="post-category">${guidance?'✦ Guidance · ':''}${esc(p.category)}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p><div class="post-actions"><button data-like="${esc(p.id)}">${liked?'♥':'♡'} ${Number(p.likes||0)+(liked?1:0)} helpful</button><button data-reply="${esc(p.id)}">↩ ${p.answers.length} ${p.answers.length===1?'reply':'replies'}</button><button data-report="${esc(p.id)}">⚑ Report</button></div></article>`}
function renderCommunity(){const canCompose=['junior','senior'].includes(data.user.role),senior=data.user.role==='senior';$('.post-composer').hidden=!canCompose;$('#open-post-composer').textContent=senior?'Share a lesson or tip with your community':'What are you working through?';$('#ask-question').innerHTML=senior?'Share guidance <span>↗</span>':'Ask the community <span>↗</span>';updateAvatar($('.avatar-you'),data.user);let posts=data.posts.filter(p=>(activeFilter==='all'||p.category===activeFilter)&&(!globalQuery||`${p.title} ${p.body} ${p.category}`.toLowerCase().includes(globalQuery.toLowerCase())));if($('#post-sort').value==='popular')posts.sort((a,b)=>b.answers.length-a.answers.length||b.likes-a.likes);$('#community-posts').innerHTML=posts.length?posts.map(renderPost).join(''):'<div class="empty-state">Nothing here yet. Start a conversation.</div>';$('#home-posts').innerHTML=data.posts.slice(0,2).map(renderPost).join('')}
