function renderOpportunities(){$('#share-opportunity').hidden=data.user.role!=='alumni';const q=$('#opportunity-search').value.trim().toLowerCase(),type=$('#opportunity-type').value;let list=data.opportunities.filter(o=>(oppTab==='all'||data.saved.includes(o.id))&&(type==='all'||o.type===type)&&`${o.title} ${o.company} ${o.description} ${o.location} ${(o.tags||[]).join(' ')}`.toLowerCase().includes(q));$('#opportunity-list').innerHTML=list.length?list.map(renderOpportunity).join(''):'<div class="empty-state" style="grid-column:1/-1">No opportunities found. Try another search or check back soon.</div>';$('#saved-count').textContent=data.saved.length}
