$('#admin-user-list').addEventListener('click',async e=>{if(data.user.role!=='admin')return;const verify=e.target.closest('[data-member-verify]');if(verify){verify.disabled=true;try{const response=await fetch('/api/admin/verify/'+encodeURIComponent(verify.dataset.memberVerify),{method:'PUT',credentials:'same-origin'}),result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to verify profile.');toast(`${result.user.name} is now verified.`);renderAdminUsers();const members=await fetch('/api/members',{credentials:'same-origin',cache:'no-store'});if(members.ok){const directory=await members.json();for(const member of directory.members){const existing=data.mentors.find(item=>item.id===member.id);if(existing)Object.assign(existing,member);else data.mentors.push(member);if(member.verified&&!data.verifiedIds.includes(member.id))data.verifiedIds.push(member.id)}renderAll()}}catch(error){toast(error.message)}finally{verify.disabled=false}return}const button=e.target.closest('[data-account-toggle]');if(!button)return;button.disabled=true;try{const response=await fetch('/api/admin/users/'+encodeURIComponent(button.dataset.accountToggle),{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:button.dataset.accountActive==='true'})}),result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to update account.');toast(`${result.user.name} account ${result.user.active?'enabled':'disabled'}.`);renderAdminUsers()}catch(error){toast(error.message)}finally{button.disabled=false}});
